'use strict';
colors.Talus='#8f9a8a';
bondDescriptions.Talus='Level 2: +1 copper ore per pick';
creatureTemperaments.Talus={trait:'Wary · trusts a steady pace',clues:['It presses flat against a boulder, watching your feet.','It shifts closer when you stay still, tapping a paw on the stone.'],actions:[['still','Stand quietly'],['tap','Tap the stone back'],['reach','Reach towards it']],best:['still','tap'],good:'It steps out from the rock and studies you.',bad:'It presses back against the stone. Give it a steadier moment.'};
const highlandsTypes=['highlandsMarker','highlandsNest'];
const highlandsNear=nearest;nearest=function(){let best=highlandsNear(),d=best?Math.hypot(best.x-player.x,best.y-player.y):43;for(const o of map.objects.filter(o=>highlandsTypes.includes(o.type))){const n=Math.hypot(o.x-player.x,o.y-player.y);if(n<d){best=o;d=n;}}return best;};
function highlandsChapter(){return HighlandsCore.chapters[state.highlands.stage];}
function highlandsQuestCard(){const q=state.highlands,c=highlandsChapter();return `<article class="story-feature">${gameIcon(q.stage===6?'check':'tool')}<small>COPPER HIGHLANDS · ${Math.min(6,q.stage+1)} / 6</small><h3>${c?c[0]:'A highland range, open at last'}</h3><p>${c?c[1]:'Talus has a home, the lift turns freely and the plateau trail is open.'}</p>${q.stage===1?`<span>${q.markers.length} / 3 survey markers found</span>`:q.stage===2?`<span>${Math.min(12,Math.max(0,state.frontier.gathered.ore-q.oreStart))} / 12 fresh ore</span>`:''}</article>`;}
function highlandsGuide(){panel('The lift rises again',highlandsQuestCard()+'<div class="actions"><button data-ui="close">Back to the trail</button><button data-front="requests">Regional requests</button></div>','Rowan’s survey','highlands');}
function rowanDialog(){const q=state.highlands;const lines=['“I’ve been surveying these highlands for years. Will you help me get the old lift moving again?”','“Somewhere out there are three survey markers I planted long ago. Find them and I’ll know where the lift’s foundations sit.”','“Fresh copper tells me the vein hasn’t run dry. Bring back twelve pieces, freshly mined.”','“Forty timber and twelve ore should mend the gearing. Meet me at the lift.”','“Something’s been watching us from the rocks. Follow the ridge trail south to the quiet outcrop.”','“You found our little surveyor’s assistant! Let’s get this lift moving.”','“Listen to those gears turn. You’ve opened the whole highland range.”'];const action=q.stage===0?'talk':q.stage===2?'ore':q.stage===5?'finish':null;panel('Rowan',`<p>${lines[q.stage]}</p>${highlandsQuestCard()}<div class="actions">${action?`<button data-highlands="${action}" ${q.stage===2&&state.frontier.gathered.ore-q.oreStart<12?'disabled':''}>${q.stage===0?'I’ll help':q.stage===2?'Show the fresh ore':'Celebrate · collect rewards'}</button>`:''}<button data-front="requests">Requests</button><button data-ui="close">See you soon</button></div>`,'Highland surveyor','highlands');}
function highlandsObjectMenu(o){const q=state.highlands;let title='The highlands',body='',action='';
 if(o.type==='highlandsMarker'){title='A weathered survey marker';body=q.markers.includes(o.marker)?'Already logged in Rowan’s notes.':'A brass marker, half buried in gravel. Worth reporting back.';if(q.stage===1&&!q.markers.includes(o.marker))action=`<button data-highlands="marker" data-marker="${o.marker}">Log this marker</button>`;}
 if(o.type==='landmark'){title='The old copper lift';body=q.stage<3?'Rowan has a plan for this place. Visit the camp to the south.':q.stage===3?'Repair the lift’s gearing with fresh timber and ore.':q.stage<6?'The gearing is sound. Follow Rowan’s plan to bring the lift back.':'A working lift. Ore gathering here now yields an extra piece.';if(q.stage===3)action=`${state.frontier.projects.lift?'<p>Materials already paid for.</p>':`<div class="ingredient-row">${chip('wood',40,state.wood)}${chip('ore',12,state.ore)}</div>`}<button data-highlands="repair" ${!state.frontier.projects.lift&&(state.wood<40||state.ore<12)?'disabled':''}>Repair the gearing</button>`;}
 if(o.type==='highlandsNest'){if(q.stage>=4&&!state.team.includes('Talus')){encounter={name:'Talus',trust:0};encounterDialog();return;}title='The quiet outcrop';body=state.team.includes('Talus')?'Talus rests in a sun-warmed hollow between the rocks. Always watching, always close.':'Small scuffmarks circle a hollow in the stone. Perhaps a working lift will bring its owner out.';}
 panel(title,`<p>${body}</p>${action}<div class="actions"><button data-highlands="guide">Rowan’s plan</button><button data-ui="close">Keep exploring</button></div>`,'Copper Highlands','highlands');
}
const highlandsInteract=interact;interact=function(){if(!dialog&&!activity){const o=nearest();if(SaveStore.status().blocked){saveMenu();return;}if(map.id==='highlands'&&o?.name==='Rowan'){rowanDialog();return;}if(map.id==='highlands'&&(highlandsTypes.includes(o?.type)||o?.type==='landmark')){faceTarget(o);highlandsObjectMenu(o);return;}}highlandsInteract();};
app.addEventListener('click',e=>{const b=e.target.closest('[data-highlands]');if(!b||b.disabled)return;const a=b.dataset.highlands;if(a==='guide'){highlandsGuide();return;}if(SaveStore.status().blocked){saveMenu();return;}const o=nearest(),allowed=['talk','ore','finish'].includes(a)?map.id==='highlands'&&o?.name==='Rowan':map.id==='highlands'&&({marker:'highlandsMarker',repair:'landmark'}[a]===o?.type);if(!allowed||(a==='marker'&&Number(b.dataset.marker)!==o.marker))return;if(HighlandsCore.act(state,a,Number(b.dataset.marker))){finish(a==='finish'?'The lift rises again! +100 coins · +3 trail marks · +6 ore':a==='marker'?`${state.highlands.markers.length} / 3 markers found`:a==='repair'?'Lift repaired! Something is still watching from the rocks.':'Rowan’s plan updated.');}if(o?.name==='Rowan')rowanDialog();else highlandsObjectMenu(o);});
const highlandsTick=tickActivities;tickActivities=function(dt){const people=map.npcs;if(map.id==='tessa')map.npcs=[];highlandsTick(dt);if(map.id==='tessa')map.npcs=people;if(HighlandsCore.act(state,'friend')){state.jobs.Talus='crystals';finish('Talus joined the highland camp. Tell Rowan the good news!');}};
const highlandsComplete=completeActivity;completeActivity=function(){if(activity?.o.type==='ore'&&state.life.active==='Talus'&&MossSystems.level(state,'Talus')>=2)state.ore++;highlandsComplete();};
const highlandsAdventure=adventureMenu;adventureMenu=function(){highlandsAdventure();if(taskTab==='story'){const b=document.createElement('button');b.dataset.highlands='guide';b.textContent=state.highlands.stage===6?'Copper Highlands · Complete':'Rowan’s highlands · '+highlandsChapter()[0];document.querySelector('.dialog .panel-tabs').after(b);}};
const highlandsMap=mapPanel;mapPanel=function(){highlandsMap();const b=document.createElement('button');b.dataset.highlands='guide';b.textContent='Copper Highlands · Rowan’s plan';document.querySelector('.dialog').append(b);};
const highlandsObject=object;object=function(o){if(map.id==='highlands'){if(o.type==='highlandsMarker'){const found=state.highlands.markers.includes(o.marker);rr(o.x-3,o.y-16,6,16,'#6b5c48');rr(o.x-7,o.y-19,14,6,found?'#c7b26a':'#8f7a4f');text(found?'✓':'?',o.x,o.y-14,found?'#eef3c0':'#f6e6ac',9);return;}if(o.type==='highlandsNest'){rr(o.x-13,o.y-4,26,8,'#7c7a6c');rr(o.x-9,o.y-8,18,7,'#a6a08c');if(state.highlands.stage>=4&&!state.team.includes('Talus'))text('?',o.x,o.y-12,'#fff0b8',12);return;}}highlandsObject(o);};
// Old saves may stand where the new markers or nest now block a path.
if(map.id==='highlands'&&blocked(map,player.x,player.y)){player.x=23*T+16;player.y=36*T+16;follower.x=player.x-24;follower.y=player.y;save();}
